import { createServerFn } from "@tanstack/react-start";
import index from "@/data/book/index.json";

// `src/data/book/` is generated by wayfare-skills' `./publish web`: edit the
// manuscript and rebuild, never these files. Only the contents (titles and
// section lists) are imported here, because this module ships to the client;
// chapter bodies live behind `getChapter` and `lib/server/book.ts`, which
// return a locked chapter's body only to a signed-in session.

export type BookMeta = {
  title: string;
  subtitle: string;
  author: string;
  affiliation: string;
  edition: string;
  date: string;
};

type FigureHead = {
  kind: "figure";
  label: string;
  number: string;
  id: string;
  captionHtml: string;
  alt: string;
  evidence?: string;
};

// "missing" is a figure whose file the publisher could not find: the page
// still shows its caption, so the reference in the text has a target.
export type FigureBlock = FigureHead &
  (
    | { type: "table"; rows: [string[], ...string[][]] }
    | { type: "card" | "diagram" | "drawn"; src: string; width: number; height: number }
    | { type: "missing" }
  );

export type ProseBlock =
  | { kind: "p" | "quote"; html: string }
  | { kind: "h3"; html: string; id: string }
  | { kind: "ul" | "ol"; items: string[] }
  | { kind: "table"; rows: [string[], ...string[][]] }
  | FigureBlock;

export type ExampleBlock = { kind: "example"; title: string; blocks: ProseBlock[] };

export type Block = ProseBlock | ExampleBlock;

export type Section = { id: string; titleHtml: string; blocks: Block[] };

export type ChapterLink = { slug: string; n: number; title: string; url: string | null };

type ChapterHead = {
  n: number;
  slug: string;
  title: string;
  minutes: number;
  free: boolean;
  url: string | null;
  prev: ChapterLink | null;
  next: ChapterLink | null;
  book: BookMeta;
};

// A chapter file as `./publish web` writes it.
// `n` is the source's number in the book's one reference list, the [n] the text links to.
export type Source = { n: number; html: string };

// An author's note, numbered in call order within its chapter.
export type Note = { n: number; html: string };

export type ChapterFile = ChapterHead & { sections: Section[]; notes: Note[]; sources: Source[] };

export type OpenChapter = ChapterFile & { locked: false };

export type LockedChapter = ChapterHead & {
  locked: true;
  teaserHtml: string;
  sections: { id: string; titleHtml: string }[];
};

export type Chapter = OpenChapter | LockedChapter;

export type ContentsEntry = {
  n: number;
  slug: string;
  title: string;
  minutes: number;
  free: boolean;
  url: string | null;
  sections: { id: string; titleHtml: string }[];
};

export type EvidenceChart = { src: string; alt: string; slug: string; width?: number; height?: number };

export type EvidenceBlock =
  | { kind: "field"; label: string; html: string }
  | { kind: "p"; html: string }
  | { kind: "ul" | "ol"; items: string[] }
  | { kind: "table"; rows: [string[], ...string[][]] };

export type EvidenceEntry = {
  anchor: string;
  label: string | null;
  slugs: string[];
  title: string | null;
  charts: EvidenceChart[];
  blocks: EvidenceBlock[];
};

export type EvidenceGroup = { title: string; entries: EvidenceEntry[] };

export type EvidenceContentsEntry = { n: number; slug: string; title: string; free: boolean; count: number };

export type EvidenceFile = EvidenceContentsEntry & { groups: EvidenceGroup[] };

export type EvidenceChapter =
  | (EvidenceFile & { locked: false })
  | (EvidenceContentsEntry & { locked: true; groups: { title: string }[] });

export type Preface = { title: string; html: string[] };

export const book: {
  meta: BookMeta;
  preface: Preface | null;
  chapters: ContentsEntry[];
  evidence: { introHtml: string[]; chapters: EvidenceContentsEntry[] };
} = index;

function validSlug(slug: unknown): string | null {
  return typeof slug === "string" && /^[a-z0-9-]{1,80}$/.test(slug) ? slug : null;
}

// The handlers' imports are dynamic so nothing server-side (the chapter JSON,
// the cookie secret) is reachable from the client bundle's module graph. A slug
// the validator refuses answers null, the same 404 as an unknown one.
export const getChapter = createServerFn({ method: "GET" })
  .validator(validSlug)
  .handler(async ({ data }) => {
    if (!data) return null;
    const { getCookie, setResponseHeader } = await import("@tanstack/react-start/server");
    const server = await import("@/lib/server/book");
    const { NO_STORE_HEADERS, sessionCookieName } = await import("@/lib/server/auth");
    const chapter = await server.chapterFor(data, () => server.hasLiveSession(getCookie(sessionCookieName())));
    // A gated page's HTML differs per reader cookie; a shared cache must not
    // hand one reader's unlocked page to the next anonymous visitor.
    if (chapter && !chapter.free) {
      for (const [name, value] of Object.entries(NO_STORE_HEADERS)) setResponseHeader(name, value);
    }
    return chapter;
  });

export const getEvidence = createServerFn({ method: "GET" })
  .validator(validSlug)
  .handler(async ({ data }) => {
    if (!data) return null;
    const { getCookie, setResponseHeader } = await import("@tanstack/react-start/server");
    const server = await import("@/lib/server/book");
    const { NO_STORE_HEADERS, sessionCookieName } = await import("@/lib/server/auth");
    const evidence = await server.evidenceFor(data, () => server.hasLiveSession(getCookie(sessionCookieName())));
    if (evidence && !evidence.free) {
      for (const [name, value] of Object.entries(NO_STORE_HEADERS)) setResponseHeader(name, value);
    }
    return evidence;
  });

const ONES =
  "Zero One Two Three Four Five Six Seven Eight Nine Ten Eleven Twelve Thirteen Fourteen Fifteen Sixteen Seventeen Eighteen Nineteen".split(
    " ",
  );
const TENS: Record<number, string> = { 2: "Twenty", 3: "Thirty", 4: "Forty" };

// The book names its chapters in words ("Chapter Fourteen"), never digits.
export function spelled(n: number): string {
  if (!Number.isInteger(n) || n < 0 || n >= 50) throw new RangeError(`spelled: ${n} is out of range`);
  if (n < 20) return ONES[n];
  return TENS[Math.floor(n / 10)] + (n % 10 ? `-${ONES[n % 10]}` : "");
}

export function plain(html: string): string {
  return html.replace(/<[^>]+>/g, "").replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");
}
